#!/bin/bash
# Sync infotable gem for Docker deployment
# This script copies the actual gem files, replacing the symlink
# Generated by InfoTable installer

# Detect if gem is vendored or symlinked
GEM_DEST="vendor/gems/infotable"

if [ ! -e "$GEM_DEST" ]; then
  echo "❌ No infotable gem found at $GEM_DEST"
  echo "   This script is only needed if you're using a vendored gem."
  exit 1
fi

# If it's not a symlink, nothing to do
if [ ! -L "$GEM_DEST" ]; then
  echo "✅ Gem is already synced (not a symlink)"
  exit 0
fi

# Get the source path from the symlink
GEM_SOURCE=$(readlink "$GEM_DEST")

if [ ! -d "$GEM_SOURCE" ]; then
  echo "❌ Symlink target not found: $GEM_SOURCE"
  exit 1
fi

echo "🔄 Syncing infotable gem for deployment..."
echo "   Source: $GEM_SOURCE"
echo "   Dest: $GEM_DEST"

# Remove symlink
echo "   Removing symlink..."
rm "$GEM_DEST"

# Copy actual gem files (excluding .git)
echo "   Copying gem files..."
rsync -a --exclude='.git' "$GEM_SOURCE/" "$GEM_DEST/"

echo "✅ Gem synced successfully"
echo "   Now you can deploy with: git push dokku main"
echo ""
echo "💡 To restore the symlink after deploying:"
echo "   rm -rf $GEM_DEST && ln -s $GEM_SOURCE $GEM_DEST"
